from datetime import datetime
from decimal import Decimal, ROUND_HALF_UP


_STAGE_MAP = {
    "P": ("prospecting", Decimal("10")),
    "Q": ("qualified", Decimal("25")),
    "N": ("negotiation", Decimal("60")),
    "W": ("closed_won", Decimal("100")),
    "L": ("closed_lost", Decimal("0")),
}


def _convert_date(value: str) -> str | None:
    if not value or value == "00000000":
        return None
    if len(value) != 8 or not value.isdigit():
        raise ValueError(f"Invalid legacy date: {value!r}")
    return datetime.strptime(value, "%Y%m%d").date().isoformat()


def _decimal_or_zero(value: str) -> Decimal:
    return Decimal(value) if value and value.strip() else Decimal(0)


def convert_opportunity(row: dict) -> dict | None:
    if row.get("DEL_FLG", "") == "Y":
        return None

    status_code = row.get("STAT_CD", "")
    try:
        stage, canonical_stage_pct = _STAGE_MAP[status_code]
    except KeyError as exc:
        raise ValueError(f"Unknown STAT_CD: {status_code!r}") from exc

    stage_pct = _decimal_or_zero(row.get("STAGE_PCT", ""))
    migration_flags = []
    if stage_pct != canonical_stage_pct:
        migration_flags.append("stage_pct_mismatch")

    currency = row.get("CURR_CD", "") or "USD"
    exponent = 0 if currency == "JPY" else 2
    amount = _decimal_or_zero(row.get("AMT", ""))
    amount_minor = int(
        (amount * (Decimal(10) ** exponent)).to_integral_value(
            rounding=ROUND_HALF_UP
        )
    )

    lost_reason = row.get("LOST_RSN", "") or None

    return {
        "opportunity_id": row.get("OPP_ID", ""),
        "account_id": row.get("ACCT_ID", ""),
        "name": row.get("OPP_NM", ""),
        "stage": stage,
        "amount_minor": amount_minor,
        "currency": currency,
        "close_date": _convert_date(row.get("CLOSE_DT", "")),
        "owner_id": row.get("OWNER_UID", ""),
        "team_code": row.get("TEAM_CD", ""),
        "lost_reason": lost_reason,
        "created_date": _convert_date(row.get("CREATE_DT", "")),
        "updated_date": _convert_date(row.get("UPD_DT", "")),
        "migration_flags": migration_flags,
    }
